//! Graphics and media surface: WebGL capability values, WebGPU availability and adapter info,
//! media-query values, plus the live checks for fonts and Web Workers.
//!
//! Everything is re-derivable from the profile alone (GPU strings, OS, browser, screen), so the
//! validator can check profiles that were not generated by Veneer.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::embedded::EXTRA_DATA_FILES;
use crate::model::{Engine, Kind, Profile};
use crate::validate::{Collector, Severity};

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Graphics {
    /// WebGL limits, shader precision and extension lists; only for GPU classes with verified data.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub webgl: Option<WebGlCaps>,
    /// `navigator.gpu` availability; `None` where no verified data exists.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub webgpu: Option<WebGpu>,
    /// Media-query values the device reports; `None` for TVs, consoles and headsets.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media: Option<Media>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebGlCaps {
    /// `getParameter` values keyed by GL constant name (arrays for range/dimension parameters).
    pub params: BTreeMap<String, Value>,
    /// `getShaderPrecisionFormat` as `[rangeMin, rangeMax, precision]`, keyed `SHADER.PRECISION`.
    pub precision: BTreeMap<String, [i32; 3]>,
    pub extensions: WebGlExtensions,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebGlExtensions {
    pub webgl: Vec<String>,
    pub webgl2: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebGpu {
    pub present: bool,
    /// `GPUAdapterInfo.vendor`, when the GPU vendor is known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vendor: Option<String>,
    /// `GPUAdapterInfo.architecture`, when the PCI device id is known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub architecture: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Media {
    /// `fine` or `coarse`.
    pub pointer: String,
    /// `hover` or `none`.
    pub hover: String,
    pub color_scheme: String,
    /// `resolution` in dppx (equals `devicePixelRatio`).
    pub resolution: f64,
    pub device_width: u32,
    pub device_height: u32,
    /// `srgb` or `p3`, only where the display gamut is documented.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color_gamut: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct WebGlClass {
    engine: Engine,
    os: Vec<String>,
    renderer_contains: String,
    params: BTreeMap<String, Value>,
    precision: BTreeMap<String, [i32; 3]>,
    extensions: WebGlExtensions,
    #[serde(default)]
    vendor_params: BTreeMap<String, BTreeMap<String, Value>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct WebGpuRule {
    engine: Engine,
    os: String,
    #[serde(default)]
    min_major: u32,
    #[serde(default)]
    min_os_major: u32,
    #[serde(default)]
    gpu_vendors: Vec<String>,
    #[serde(default)]
    gpu_architectures: Vec<String>,
    #[serde(default)]
    browsers: Vec<String>,
    #[serde(default = "enabled_default")]
    enabled: bool,
}

fn enabled_default() -> bool {
    true
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct PciVendor {
    vendor: String,
    device_sets: Vec<DeviceSet>,
}

#[derive(Deserialize)]
struct DeviceSet {
    mask: String,
    architecture: BTreeMap<String, Vec<String>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct WebGpuData {
    availability: Vec<WebGpuRule>,
    pci_vendors: Vec<PciVendor>,
}

struct Data {
    webgl: Vec<WebGlClass>,
    webgpu: WebGpuData,
}

fn data() -> Result<&'static Data, String> {
    static DATA: OnceLock<Result<Data, String>> = OnceLock::new();
    DATA.get_or_init(|| {
        let file = |stem: &str| {
            EXTRA_DATA_FILES
                .iter()
                .find(|(s, _)| *s == stem)
                .map(|(_, text)| *text)
                .ok_or_else(|| format!("data/extra/{stem}.json is missing"))
        };
        let webgl = EXTRA_DATA_FILES
            .iter()
            .filter(|(stem, _)| stem.starts_with("gpu-angle-"))
            .map(|(stem, text)| {
                serde_json::from_str(text).map_err(|e| format!("data/extra/{stem}.json: {e}"))
            })
            .collect::<Result<Vec<WebGlClass>, String>>()?;
        let webgpu = serde_json::from_str(file("gpu-webgpu")?)
            .map_err(|e| format!("data/extra/gpu-webgpu.json: {e}"))?;
        Ok(Data { webgl, webgpu })
    })
    .as_ref()
    .map_err(Clone::clone)
}

/// GPU vendor family named in a WebGL renderer string, in the spelling `GPUAdapterInfo` uses.
fn gpu_vendor(renderer: &str) -> Option<&'static str> {
    let r = renderer.to_ascii_lowercase();
    [
        ("nvidia", "nvidia"),
        ("radeon", "amd"),
        ("amd", "amd"),
        ("intel", "intel"),
        ("adreno", "qualcomm"),
        ("qualcomm", "qualcomm"),
        ("mali", "arm"),
        ("powervr", "imagination"),
        ("xclipse", "samsung"),
        ("apple", "apple"),
    ]
    .into_iter()
    .find(|(needle, _)| r.contains(needle))
    .map(|(_, vendor)| vendor)
}

/// PCI device id from an ANGLE renderer string such as `... (0x00002504) Direct3D11 ...`.
fn pci_device_id(renderer: &str) -> Option<u32> {
    let start = renderer.find("(0x")? + 3;
    let hex: String = renderer[start..]
        .chars()
        .take_while(char::is_ascii_hexdigit)
        .take(8)
        .collect();
    u32::from_str_radix(&hex, 16).ok()
}

fn parse_hex(s: &str) -> Option<u32> {
    u32::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).ok()
}

fn architecture(data: &Data, vendor: &str, device: u32) -> Option<String> {
    let v = data
        .webgpu
        .pci_vendors
        .iter()
        .find(|v| v.vendor == vendor)?;
    v.device_sets.iter().find_map(|set| {
        let mask = parse_hex(&set.mask)?;
        set.architecture.iter().find_map(|(arch, ids)| {
            ids.iter()
                .any(|id| parse_hex(id) == Some(device & mask))
                .then(|| arch.clone())
        })
    })
}

fn renderer(p: &Profile) -> &str {
    p.webgl
        .unmasked_renderer
        .as_deref()
        .unwrap_or(&p.webgl.renderer)
}

fn leading_number(s: &str) -> Option<u32> {
    let digits: String = s.chars().take_while(char::is_ascii_digit).collect();
    digits.parse().ok()
}

/// Chromium version under a Chromium-based browser (Samsung Internet 28 runs Chromium 130).
fn engine_major(p: &Profile) -> u32 {
    if p.browser.engine == Engine::Chromium {
        if let Some(i) = p.navigator.user_agent.find("Chrome/") {
            if let Some(v) = leading_number(&p.navigator.user_agent[i + 7..]) {
                return v;
            }
        }
    }
    p.browser.major
}

fn webgl_caps(data: &Data, p: &Profile, vendor: Option<&str>) -> Option<WebGlCaps> {
    let r = renderer(p);
    let class = data.webgl.iter().find(|c| {
        c.engine == p.browser.engine && c.os.contains(&p.os.id) && r.contains(&c.renderer_contains)
    })?;
    let mut params = class.params.clone();
    if let Some(over) = vendor.and_then(|v| class.vendor_params.get(v)) {
        params.extend(over.iter().map(|(k, v)| (k.clone(), v.clone())));
    }
    Some(WebGlCaps {
        params,
        precision: class.precision.clone(),
        extensions: class.extensions.clone(),
    })
}

fn webgpu(data: &Data, p: &Profile, vendor: Option<&str>) -> Option<WebGpu> {
    let arch =
        vendor.and_then(|v| pci_device_id(renderer(p)).and_then(|id| architecture(data, v, id)));
    let covering: Vec<&WebGpuRule> = data
        .webgpu
        .availability
        .iter()
        .filter(|r| {
            r.engine == p.browser.engine
                && r.os == p.os.id
                && (r.browsers.is_empty() || r.browsers.contains(&p.browser.id))
        })
        .collect();
    if covering.is_empty() {
        return None;
    }
    let major = engine_major(p);
    let os_major = leading_number(&p.os.version).unwrap_or(0);
    let present = covering.iter().any(|r| {
        r.enabled
            && major >= r.min_major
            && os_major >= r.min_os_major
            && (r.gpu_vendors.is_empty()
                || vendor.is_some_and(|v| r.gpu_vendors.iter().any(|g| g == v)))
            && (r.gpu_architectures.is_empty()
                || arch
                    .as_ref()
                    .is_some_and(|a| r.gpu_architectures.contains(a)))
    });
    // Vendor and architecture names follow Dawn, so they are only known for Chromium.
    let known_vendor = vendor.filter(|v| {
        p.browser.engine == Engine::Chromium
            && data.webgpu.pci_vendors.iter().any(|pv| pv.vendor == *v)
    });
    Some(WebGpu {
        present,
        vendor: known_vendor.filter(|_| present).map(str::to_owned),
        architecture: arch.filter(|_| present && known_vendor.is_some()),
    })
}

fn media(p: &Profile) -> Option<Media> {
    let (pointer, hover) = match p.device.kind {
        Kind::Phone | Kind::Tablet => ("coarse", "none"),
        Kind::Desktop | Kind::Laptop => ("fine", "hover"),
        _ => return None,
    };
    Some(Media {
        pointer: pointer.into(),
        hover: hover.into(),
        color_scheme: "light".into(),
        resolution: p.screen.device_pixel_ratio,
        device_width: p.screen.width,
        device_height: p.screen.height,
        // Every iPhone in the dataset (iPhone 7 and later) has a Display P3 panel.
        color_gamut: p.device.id.starts_with("iphone-").then(|| "p3".into()),
    })
}

/// What the profile's graphics section must be, derived from the rest of the profile.
pub(crate) fn expected(p: &Profile) -> Result<Graphics, String> {
    let data = data()?;
    let vendor = gpu_vendor(renderer(p));
    Ok(Graphics {
        webgl: webgl_caps(data, p, vendor),
        webgpu: webgpu(data, p, vendor),
        media: media(p),
    })
}

pub(crate) fn derive(p: &Profile) -> Option<Graphics> {
    expected(p).ok()
}

pub(crate) fn validate(p: &Profile, c: &mut Collector) {
    let Some(g) = &p.ext.graphics else { return };
    let e = match expected(p) {
        Ok(e) => e,
        Err(msg) => return c.push(Severity::Error, "graphics.data", msg),
    };
    c.error_if(g.webgl != e.webgl, "graphics.webgl", || {
        "WebGL limits or extensions do not match the profile's GPU and browser".into()
    });
    c.error_if(g.webgpu != e.webgpu, "graphics.webgpu", || {
        format!(
            "WebGPU should be {:?} for this browser, OS and GPU",
            e.webgpu
        )
    });
    c.error_if(g.media != e.media, "graphics.media", || {
        format!("media-query values should be {:?}", e.media)
    });
}

/// Families the collector probes by measurement (`collect/70-fonts.js`); keep both lists equal.
pub(crate) const FONT_PROBES: [&str; 24] = [
    "Arial",
    "Calibri",
    "Segoe UI",
    "Segoe UI Variable",
    "Cascadia Code",
    "Bahnschrift",
    "Consolas",
    "Cambria",
    "Candara",
    "Helvetica Neue",
    "Menlo",
    "Monaco",
    "Avenir",
    "Futura",
    "Gill Sans",
    "Optima",
    "Ubuntu",
    "DejaVu Sans",
    "Liberation Sans",
    "Noto Sans",
    "Roboto",
    "Cantarell",
    "Arial Nova",
    "Courier New",
];

pub(crate) fn live_checks(p: &Profile) -> Vec<(String, Value)> {
    let mut out = Vec::new();
    let Some(g) = &p.ext.graphics else {
        return out;
    };
    if let Some(m) = &g.media {
        out.extend([
            ("/graphics/media/pointer".to_owned(), json!(m.pointer)),
            ("/graphics/media/hover".to_owned(), json!(m.hover)),
            (
                "/graphics/media/colorScheme".to_owned(),
                json!(m.color_scheme),
            ),
            ("/graphics/media/resolution".to_owned(), json!(m.resolution)),
            (
                "/graphics/media/deviceWidth".to_owned(),
                json!(m.device_width),
            ),
            (
                "/graphics/media/deviceHeight".to_owned(),
                json!(m.device_height),
            ),
        ]);
        if let Some(gamut) = &m.color_gamut {
            out.push(("/graphics/media/colorGamut".to_owned(), json!(gamut)));
        }
    }
    if let Some(w) = &g.webgl {
        for (name, value) in &w.params {
            out.push((format!("/graphics/webgl/params/{name}"), value.clone()));
        }
        for (name, value) in &w.precision {
            out.push((format!("/graphics/webgl/precision/{name}"), json!(value)));
        }
        // Extension lists are not compared: the init script can hide extensions but not add ones the
        // host GPU lacks (headless SwiftShader has fewer), so equality would fail on correct pages.
    }
    // Only absence is checked: presence also depends on a secure context and a usable adapter.
    if g.webgpu.as_ref().is_some_and(|w| !w.present) {
        out.push(("/graphics/webgpu/present".to_owned(), json!(false)));
    }
    for font in FONT_PROBES {
        if !p.fonts.iter().any(|f| f.eq_ignore_ascii_case(font)) {
            out.push((format!("/graphics/fonts/{font}"), json!(false)));
        }
    }
    let n = &p.navigator;
    out.extend([
        ("/worker/userAgent".to_owned(), json!(n.user_agent)),
        ("/worker/platform".to_owned(), json!(n.platform)),
        ("/worker/language".to_owned(), json!(n.language)),
        (
            "/worker/hardwareConcurrency".to_owned(),
            json!(n.hardware_concurrency),
        ),
    ]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_files_parse() {
        let d = data().unwrap();
        assert!(!d.webgl.is_empty());
        assert!(!d.webgpu.availability.is_empty());
    }

    #[test]
    fn pci_ids_map_to_dawn_architectures() {
        let d = data().unwrap();
        let arch = |v: &str, r: &str| architecture(d, v, pci_device_id(r).unwrap());
        assert_eq!(
            arch("nvidia", "ANGLE (NVIDIA, NVIDIA GeForce RTX 3060 (0x00002504) Direct3D11 vs_5_0 ps_5_0, D3D11)").as_deref(),
            Some("ampere")
        );
        assert_eq!(
            arch("nvidia", "x (0x00002882) y").as_deref(),
            Some("lovelace")
        );
        assert_eq!(arch("amd", "x (0x000073FF) y").as_deref(), Some("rdna-2"));
        assert_eq!(arch("amd", "x (0x00001638) y").as_deref(), Some("gcn-5"));
        assert_eq!(
            arch("intel", "x (0x00009A49) y").as_deref(),
            Some("gen-12-lp")
        );
        // Measured in this repository's Chromium on an Intel Meteor Lake GPU.
        assert_eq!(arch("intel", "x (0x00007D67) y").as_deref(), Some("xe-lpg"));
        assert_eq!(pci_device_id("Apple GPU"), None);
    }

    #[test]
    fn vendors_from_renderer_strings() {
        assert_eq!(
            gpu_vendor("ANGLE (AMD, Radeon R9 200 Series Direct3D11 vs_5_0 ps_5_0), or similar"),
            Some("amd")
        );
        assert_eq!(gpu_vendor("Adreno (TM) 740"), Some("qualcomm"));
        assert_eq!(gpu_vendor("Mali-G715"), Some("arm"));
        assert_eq!(
            gpu_vendor("PowerVR D-Series DXT-48-1536"),
            Some("imagination")
        );
        assert_eq!(gpu_vendor("Apple GPU"), Some("apple"));
    }

    fn profile(os: &str, browser: &str, gpu: Option<&str>, seed: &str) -> Profile {
        crate::generate(&crate::model::Constraints {
            os: Some(os.into()),
            browser: Some(browser.into()),
            gpu_vendor: gpu.map(Into::into),
            seed: Some(seed.into()),
            ..Default::default()
        })
        .unwrap()
    }

    #[test]
    fn derived_values_follow_gpu_and_platform() {
        let win = profile("windows", "chrome", Some("nvidia"), "g1");
        let g = win.ext.graphics.as_ref().unwrap();
        let w = g.webgl.as_ref().unwrap();
        assert_eq!(w.params["MAX_VERTEX_UNIFORM_VECTORS"], json!(4095));
        assert_eq!(w.params["MAX_TEXTURE_SIZE"], json!(16384));
        let gpu = g.webgpu.as_ref().unwrap();
        assert!(gpu.present);
        assert_eq!(gpu.vendor.as_deref(), Some("nvidia"));

        let intel = profile("windows", "edge", Some("intel"), "g2");
        let w = intel.ext.graphics.as_ref().unwrap().webgl.as_ref().unwrap();
        assert_eq!(w.params["MAX_VERTEX_UNIFORM_VECTORS"], json!(4096));

        let ff = profile("windows", "firefox", None, "g3");
        let g = ff.ext.graphics.as_ref().unwrap();
        assert!(g.webgl.is_none(), "no verified Firefox WebGL data");
        assert_eq!(g.webgpu.as_ref().unwrap().vendor, None);

        let linux = profile("linux", "chrome", None, "g4");
        assert!(
            !linux
                .ext
                .graphics
                .as_ref()
                .unwrap()
                .webgpu
                .as_ref()
                .unwrap()
                .present
        );

        let phone = profile("ios", "safari", None, "g5");
        let m = phone.ext.graphics.as_ref().unwrap().media.as_ref().unwrap();
        assert_eq!(
            (m.pointer.as_str(), m.color_gamut.as_deref()),
            ("coarse", Some("p3"))
        );
    }

    #[test]
    fn validator_catches_tampered_graphics() {
        let mut p = profile("windows", "chrome", Some("amd"), "g6");
        assert!(crate::validate::validate(&p).issues.is_empty());
        if let Some(g) = p.ext.graphics.as_mut() {
            g.webgpu = Some(WebGpu {
                present: false,
                vendor: None,
                architecture: None,
            });
            if let Some(m) = g.media.as_mut() {
                m.pointer = "coarse".into();
            }
        }
        let rules: Vec<String> = crate::validate::validate(&p)
            .issues
            .into_iter()
            .map(|i| i.rule)
            .collect();
        assert_eq!(rules, ["graphics.webgpu", "graphics.media"]);
    }
}
